import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

@Component
public class OrderPricing {

    private static final double VAT_PERCENT = 23.0;

    /** "12", "12.5", "12,5" or "12.25" – at most two decimals, 0 to 100 inclusive. */
    private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})(?:[.,](\\d{1,2}))?");
    private static final long MAX_BASIS_POINTS = 10_000;

    public Money withVat(Money net) {
        double gross = net.minorUnits() * (100 + VAT_PERCENT) / 100;
        return new Money(Math.round(gross), net.currency());
    }

    /** Parses a percentage typed into a form into whole basis points (12.5 becomes 1250). */
    public long basisPoints(String percent) {
        Matcher m = PERCENT.matcher(percent == null ? "" : percent.trim());
        if (!m.matches()) {
            throw new ShopProblem("INVALID_PERCENT", "Not a percentage: " + percent);
        }
        long whole = Long.parseLong(m.group(1));
        long hundredths = 0;
        if (m.group(2) != null) {
            String fraction = m.group(2);
            hundredths = Long.parseLong(fraction.length() == 1 ? fraction + "0" : fraction);
        }
        long basisPoints = whole * 100 + hundredths;
        if (basisPoints > MAX_BASIS_POINTS) {
            throw new ShopProblem("INVALID_PERCENT", "Percentage must be between 0 and 100: " + percent);
        }
        return basisPoints;
    }

    /** The amount taken off {@code total} at {@code basisPoints}, rounded half up to a whole minor unit. */
    public Money discount(Money total, long basisPoints) {
        long product = Math.multiplyExact(Math.multiplyExact(total.minorUnits(), basisPoints), 2L);
        // floor((2 * amount * rate + 10000) / 20000) == round-half-up(amount * rate / 10000)
        long rounded = Math.floorDiv(Math.addExact(product, MAX_BASIS_POINTS), 2 * MAX_BASIS_POINTS);
        return new Money(rounded, total.currency());
    }
}
}

